import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Roles & Permissions","description":"How VERA four permission roles scope data visibility, financial access, and available console actions.","frontmatter":{"description":"How VERA four permission roles scope data visibility, financial access, and available console actions."},"headers":[],"relativePath":"reference/concepts/roles.md","filePath":"reference/concepts/roles.md"}'),s={name:"reference/concepts/roles.md"};function o(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="roles-permissions" tabindex="-1">Roles &amp; Permissions <a class="header-anchor" href="#roles-permissions" aria-label="Permalink to &quot;Roles &amp; Permissions&quot;">​</a></h1><p>VERA has four permission roles. Each role scopes what data is visible and what actions are allowed.</p><hr><h2 id="the-four-roles" tabindex="-1">The four roles <a class="header-anchor" href="#the-four-roles" aria-label="Permalink to &quot;The four roles&quot;">​</a></h2><h3 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h3><p>Full access. Owners see everything including dollar amounts, all projects, all users, rates, and liabilities.</p><p><strong>Owners can:</strong></p><ul><li>Create, rename, and delete projects</li><li>Set project budgets and deadlines</li><li>Assign project managers</li><li>Add, update, deactivate, and reactivate users</li><li>Promote users to Manager or Owner</li><li>Set hourly cost rates (Rate History)</li><li>Create and cancel liabilities</li><li>View all financial data (revenue, cost, margin, contract values)</li><li>See all projects across all clients</li><li>Approve or reject time off requests</li><li>Log their own time off directly — no approval flow required</li><li>Access all tools without restriction</li></ul><h3 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h3><p>Owner-level access, with one deliberate difference: an Admin is <strong>not counted in team statistics</strong>. Admins are the people who run the agency&#39;s operations — the kind of person who owns or oversees the system but does not personally deliver billable client work. Giving them the same visibility as an Owner is right; counting them in utilisation or capacity is not, because they would drag every team-wide number down with hours they were never expected to bill.</p><p><strong>Admins can:</strong></p><ul><li>Everything an Owner can — full financial visibility (dollar amounts, rates, contract values, margins), all projects, all users, deadlines, liabilities, and every tool without restriction</li><li>Still log their own time and hold allocation envelopes — their individual records are untouched</li></ul><p><strong>Admins are excluded from:</strong></p><ul><li>Every team-delivery statistic — team availability, capacity forecasts, utilisation, and any &quot;team of N&quot; denominator. If a team of 11 includes one Admin, the rollups are computed over the 10 people who actually deliver work, so the Admin&#39;s presence never dilutes the numbers.</li></ul><p>This is the only way an Admin differs from an Owner. The stored role stays <code>admin</code> (it is never silently converted to <code>owner</code>), which is exactly what keeps the statistics exclusion working.</p><h3 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h3><p>Scoped access. Managers see their assigned projects and percentages — never dollar amounts. They are the day-to-day operational role.</p><p><strong>Managers can:</strong></p><ul><li>View their assigned projects (where they are the PM)</li><li>See percentages: budget % used, margin %, utilisation %</li><li>See project deadlines (needed for delivery planning)</li><li>Set the deadline on projects where they are the assigned PM</li><li>Create and manage envelopes for their assigned projects</li><li>Enable/disable tasks and set task budgets for their assigned projects</li><li>Approve or reject time off requests</li><li>Log sick days and leave on behalf of team members</li><li>View whole-team capacity and availability (hours only — no cost or billing figures); project burn rate for assigned projects</li><li>See liabilities for their assigned projects (read only)</li></ul><p><strong>Managers cannot:</strong></p><ul><li>Create or delete projects</li><li>Set project-level budgets (Tier 1) — only Owners do this</li><li><strong>Write</strong> <code>contract_value</code>, <code>billing_rate</code>, or <code>hours_budget</code> via <code>update_project</code> — these fields are owner-only on write (mirrors the read-side isolation). Attempting to update them returns <code>❌ Failed: Only owners can change a project&#39;s …</code></li><li>Promote users or change roles</li><li>See dollar amounts, rates, or contract values</li><li>Access projects they are not assigned to as PM</li><li>Create or cancel liabilities</li></ul><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>The base role. Users track their own time and manage their own schedule.</p><p><strong>Users can:</strong></p><ul><li>Log time for themselves</li><li>Edit and delete their own time entries</li><li>View their own time history</li><li>See their own envelopes (&quot;what should I work on?&quot;)</li><li>Request time off (PTO, sick, leave)</li><li>View their own time off history</li></ul><p><strong>Users cannot:</strong></p><ul><li>Log time for others</li><li>View other people&#39;s time entries</li><li>See project deadlines (deadlines are never shown to Users under any circumstances)</li><li>See financial data of any kind</li><li>Manage envelopes, projects, or other users</li><li>Approve time off requests</li></ul><p><strong>Console access:</strong> Users now have a console surface at <code>/console/time</code>, scoped to logging, viewing, editing, and deleting their own time entries. This is the same permission boundary as Slack (own entries only) — just a second surface for the same capability. All other <code>/console/*</code> routes remain manager+/owner-only for the <code>user</code> role. <code>vendor</code> users have no console access.</p><hr><h2 id="permission-matrix" tabindex="-1">Permission matrix <a class="header-anchor" href="#permission-matrix" aria-label="Permalink to &quot;Permission matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Owner</th><th>Manager</th><th>User</th></tr></thead><tbody><tr><td>Log time (self)</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Log time (others)</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>View own time</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>View team time</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>Create project</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Delete project</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Set project budget (Tier 1)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Allocate hours (Tier 2)</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>Set task budgets</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>Assign PM</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Add users</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Change user roles</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Deactivate/reactivate users</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>See project deadlines</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>Set project deadline</td><td>✅</td><td>✅ (PM of project only)</td><td>❌</td></tr><tr><td>See dollar amounts / revenue</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>See budget percentages</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>See rates (hourly cost)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>See contract values</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Set contract_value / billing_rate / hours_budget</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Create liabilities</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>View liabilities</td><td>✅</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>Cancel liabilities</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Approve time off</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>Request time off (own)</td><td>✅ direct</td><td>✅ pending</td><td>✅ pending</td></tr><tr><td>Add company holidays</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>View capacity forecast</td><td>✅</td><td>✅ (hours only)</td><td>❌</td></tr></tbody></table><p><strong>Admin</strong> holds the same permissions as <strong>Owner</strong> in every row above (owner-level access). The single difference is not an action permission but a statistics one: an Admin is <strong>excluded from every team-delivery rollup</strong> — team availability, capacity forecasts, utilisation, and any &quot;team of N&quot; denominator — alongside vendors, who sell deliverables rather than time. An Admin can still log their own time and hold allocation envelopes; only the aggregate team numbers leave them out.</p><hr><h2 id="role-assignment" tabindex="-1">Role assignment <a class="header-anchor" href="#role-assignment" aria-label="Permalink to &quot;Role assignment&quot;">​</a></h2><p>Roles are set in the <code>03. Users</code> sheet:</p><ul><li><code>&quot;owner&quot;</code> — full access</li><li><code>&quot;admin&quot;</code> — owner-level access, excluded from team statistics</li><li><code>&quot;manager&quot;</code> — project-scoped access</li><li><code>&quot;user&quot;</code> — self-only access</li></ul><p>Users are auto-registered with the <code>user</code> role when they first message the bot. Only Owners and Admins can promote a user to Manager, Owner, or Admin (&quot;make @alex an admin&quot;).</p><h3 id="promoting-via-assign-pm" tabindex="-1">Promoting via assign_pm <a class="header-anchor" href="#promoting-via-assign-pm" aria-label="Permalink to &quot;Promoting via assign_pm&quot;">​</a></h3><p>The <code>assign_pm</code> tool is a shortcut that promotes a User to Manager <strong>and</strong> assigns them to a project in a single step. If someone needs to be made PM before they&#39;ve messaged the bot, they need to message it first so VERA can register their Slack ID.</p><hr><h2 id="deadlines-and-users" tabindex="-1">Deadlines and Users <a class="header-anchor" href="#deadlines-and-users" aria-label="Permalink to &quot;Deadlines and Users&quot;">​</a></h2><p>Deadlines are visible to Owners and Managers. <strong>They are never shown to Users under any circumstances.</strong> This is a deliberate design decision — deadlines exist for financial accrual and capacity planning, not for individual task management. When a User asks about a project deadline, VERA omits it from the response without acknowledging that a deadline exists.</p><hr><h2 id="financial-data-in-public-spaces" tabindex="-1">Financial data in public spaces <a class="header-anchor" href="#financial-data-in-public-spaces" aria-label="Permalink to &quot;Financial data in public spaces&quot;">​</a></h2><p>Financial figures — hourly rates, contract values, agreed liability amounts — must never appear in shared or public Slack channels (including the audit channel). The audit channel is visible to anyone subscribed, which may include Users who are not permitted to see financial data.</p><p>VERA enforces this in two ways:</p><ul><li><strong><code>set_rate</code></strong> does not post to the audit channel at all — rate changes are recorded in the server console only, never in Slack.</li><li><strong><code>create_liability</code></strong> posts an audit message recording the action (vendor, project, description) but <strong>never includes the dollar amount</strong>. The actual figures are only accessible to Owners via direct conversation with the bot.</li></ul><hr><h2 id="inactive-users" tabindex="-1">Inactive users <a class="header-anchor" href="#inactive-users" aria-label="Permalink to &quot;Inactive users&quot;">​</a></h2><p>Deactivated users (<code>status = &quot;inactive&quot;</code>) cannot log time or take any actions. Their historical entries are preserved. They appear in <code>list_users</code> with <code>(inactive)</code> next to their name.</p><p>Use <code>reactivate_user</code> to restore access.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/blog/06-roles-and-dollars.html">The Data Is Only Worth Protecting If It&#39;s Worth Something</a> — the thinking behind three access levels and why owners, managers, and users need different views</li></ul>',53)])])}const m=t(s,[["render",o]]);export{p as __pageData,m as default};
